/* One curriculum for the engine and the embedded academy. The skill registry
 * is independent of the lessons: coverage cannot grow by adding easy drills. */
const TRAINING_VERSION = 1;
function trainingText(key, ru, en) {
  const k = 'academy.' + key;
  ET.dicts.ru[k] = ru; ET.dicts.en[k] = en;
  return k;
}

