function trainingTarget(id, n = 0) {
  const side = n % 2 ? -1 : 1;
  const zones = {
    center: { x0: -.30, x1: .30, z0: -1.28, z1: -.08 },
    left: { x0: -.70, x1: -.12, z0: -1.28, z1: -.08 },
    right: { x0: .12, x1: .70, z0: -1.28, z1: -.08 },
    short: { x0: -.65, x1: .65, z0: -.62, z1: -.04 },
    deep: { x0: -.65, x1: .65, z0: -1.32, z1: -.78 },
  };
  if (id === 'mixed') id = ['left', 'right', 'short', 'deep', 'center'][n % 5];
  if (id === 'sides') id = side > 0 ? 'right' : 'left';
  if (id === 'depth') id = n % 2 ? 'deep' : 'short';
  if (id === 'corners') return { x0: side > 0 ? .22 : -.70, x1: side > 0 ? .70 : -.22, z0: -1.32, z1: -.76 };
  return zones[id] ? { ...zones[id] } : null;
}
function trainingInTarget(p, zone) {
  return !zone || (!!p && Number.isFinite(p.x) && Number.isFinite(p.z) && p.x >= zone.x0 && p.x <= zone.x1 && p.z >= zone.z0 && p.z <= zone.z1);
}

