function trainingLesson(id, module, stroke, ru, en, skills, opts = {}) {
  const guide = TRAIN_GUIDES[stroke];
  return { id, module, stroke, skills, title: trainingText('lesson.' + id + '.title', ru[0], en[0]),
    goal: trainingText('lesson.' + id + '.goal', ru[1], en[1]),
    context: trainingText('lesson.' + id + '.context', ru[2], en[2]),
    quiz: { prompt: trainingText('lesson.' + id + '.quiz', ru[3], en[3]), options: opts.options || [stroke, 'force', 'hold'], answer: opts.answer || stroke },
    tip: guide.briefTouch, mouseTip: guide.briefMouse, need: 3, feed: opts.serve ? null : TRAIN_FEEDS[opts.feed || 'normal'],
    coach: 'ring', ...opts };
}
